#!/bin/bash
step() { local name=$1; local dir=$2; shift 2; : > /workspace/rea-article/transcripts/$name.txt; for c in "$@"; do echo "\$ $c" >> /workspace/rea-article/transcripts/$name.txt; bash -c "source ~/.local/rea-env.sh; cd $dir; $c" >> /workspace/rea-article/transcripts/$name.txt 2>&1; echo >> /workspace/rea-article/transcripts/$name.txt; done; }
C=/workspace/re/crackme; L=/workspace/re/lab
step t15-mcp-replay $C "jq -c '{tool: \"trace_feature\", evidence_id, confidence, match: .normalized_result.matches[0].value, refs: [.normalized_result.references[].source_address], in: .normalized_result.references[0].containing_procedure.procedure.name}' notes/mcp-trace-access-granted.json" "jq -c '{tool: \"annotate_native_function\", evidence_id, name: .normalized_result.annotations.name, comment: .normalized_result.annotations.comment}' notes/mcp-annotate.json" "jq -c '{exported_records: .records|length, unknowns: [.unknowns[]? | {unknown_id, status, severity}]}' notes/evidence.json"
step t17-js-ipc $L "jq -r '.normalized_result.graph.nodes[] | select(.kind|test(\"browser-window|context-bridge|ipc-\")) | [.kind, .observations[0].label, (.observations[0].properties.source_path // .observations[0].properties.side // \"\")] | @tsv' jsapp-evidence.json"
